 using Microsoft.VisualStudio.TestTools.UnitTesting;

 namespace MyApp.Tests;

 [TestClass]
 public class ExceptionTests
 {
     [TestMethod]
     public void Throws_ExactType()
     {
         Assert.ThrowsExactly<InvalidOperationException>(() => throw new InvalidOperationException("x"));
     }

     [TestMethod]
     public void ThrowsAny_AcceptsDerived()
     {
         try
         {
             throw new InvalidOperationException("x");
         }
         catch (AssertFailedException)
         {
             throw;
         }
         catch (Exception ex)
         {
             Assert.IsInstanceOfType<Exception>(ex);
             return;
         }

         Assert.Fail("Expected an exception but none was thrown.");
     }

     [TestMethod]
     public async Task ThrowsAsync_ExactType()
     {
         await Assert.ThrowsExactlyAsync<InvalidOperationException>(
             async () => { await Task.Yield(); throw new InvalidOperationException(); });
     }
 }

